import React, { useState, useRef, useEffect } from "react";
import { Client } from "@gradio/client";
import ReactMarkdown from "react-markdown";

const ChatAI = ({ entries }) => {
    const [userMessage, setUserMessage] = useState("");
    const [chatHistory, setChatHistory] = useState([]);
    const [loading, setLoading] = useState(false);
    const chatEndRef = useRef(null);

    const handleSendMessage = async () => {
        if (!userMessage.trim()) return;
        setLoading(true);

        const timestamp = new Date().toLocaleTimeString();
        setChatHistory(prev => [...prev, { sender: "user", text: userMessage, time: timestamp }]);

        try {
            setUserMessage('')
            const client = await Client.connect("shivamsharmav/financetraker");
            console.log(client,'RAM')
            const result = await client.predict("/chat", {
                message: `Data: ${JSON.stringify(entries)}\nQuestion: ${userMessage}`,
 system_message: `
You are a Smart Finance Assistant AI.
You only use the provided JSON data to analyze the user's finances.

The JSON contains records like income, expense, borrow, borrowReturn, transfer, and investment with fields:
- id, type, description, amount, category, bank, date.

**Borrow / BorrowReturn Handling:**
- **borrow** → Money the user lent to someone. This **reduces available balance** and is **not income**.
- **borrowReturn** → Money received back from someone the user lent to. This **increases available balance** and is **treated as cash inflow like income**.
- **Net effect on balance** = borrowReturn - borrow
- **Calculations and Dashboard:**
  - Income totals: Include borrowReturn, **exclude borrow**.
  - Expense totals: Include borrow, **exclude borrowReturn**.
  - Bank-wise balance: Adjust for borrow and borrowReturn to reflect real funds.

Your tasks:
1. **Data Accuracy**  
   - Only calculate using the JSON data.  
   - Respect the "bank" field → give bank-wise balance if asked.  
   - If data is missing, reply clearly: "Data not available in records."

2. **Financial Insights**  
   - Show totals, balances, and summaries (daily, monthly, yearly).  
   - Compare categories (e.g., food vs entertainment vs bills).  
   - Identify high-spending categories for the month and call them out.  
   - Highlight irregular or one-time big expenses.  
   - Point out if spending is higher than income in any month.  

3. **Advisory Suggestions**  
   - Suggest practical ways to reduce expenses (e.g., "This month, your entertainment spend was 40% of expenses. Try reducing dining out").  
   - Suggest savings opportunities (e.g., "You can save more if you limit daily food expenses under ₹500").  
   - If the user asks "how to reduce expense", show top 2–3 categories where cuts are possible.  
   - If user asks "where did I spend extra?", highlight categories with higher-than-average spends compared to other days/weeks.  

4. **Formatting**  
   - Use Markdown for clarity:  
     - **Bold** for key numbers.  
     - Bullet points for breakdowns.  
     - Tables where comparison is needed.  
   - Always use the ₹ symbol for amounts.

Keep responses structured, concise, and insightful like a financial advisor, not just raw numbers.
`
,
                max_tokens: 1000,
                temperature: 0.3,
                top_p: 0.5
            });
            console.log(result, 'RAM')
            const aiTimestamp = new Date().toLocaleTimeString();

            // result.data might be array or string
            const aiText = Array.isArray(result.data) ? result.data.join("\n") : result.data;

            setChatHistory(prev => [...prev, { sender: "ai", text: aiText, time: aiTimestamp }]);
        } catch (err) {
            console.error(err);
            setChatHistory(prev => [...prev, { sender: "ai", text: "Error fetching response.", time: new Date().toLocaleTimeString() }]);
        } finally {
            setLoading(false);
            setUserMessage("");
        }
    };

    // Auto scroll
    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [chatHistory]);

    return (
        <div
            style={{
                maxWidth: "99%",
                margin: "10px auto",
                fontFamily: "'Segoe UI', sans-serif",
                borderRadius: "18px",
                boxShadow: "0 0 15px rgba(0,0,0,0.1)",
                background: "#f9fafb",
                display: "flex",
                flexDirection: "column",
                height: "80vh",
                border: "1px solid #e5e7eb",
            }}
        >
            {/* Header */}
            <div
                style={{
                    padding: "12px",
                    borderRadius: "16px 16px 0px 0px",
                    borderBottom: "1px solid #e5e7eb",
                    background: "linear-gradient(90deg,#5A8DEE,#42E695)",
                    color: "white",
                    fontWeight: "bold",
                    fontSize: "1rem",
                    textAlign: "center",
                    letterSpacing: "0.5px",
                    textShadow: "0 0 4px rgba(0,0,0,0.2)",
                }}
            >
                🤖 Your AI-Powered Mentor
            </div>

            {/* Chat container */}
            <div
                style={{
                    flex: 1,
                    overflowY: "auto",
                    padding: "12px",
                    display: "flex",
                    flexDirection: "column",
                    gap: "10px",
                    background: "#ffffff",
                }}
            >
                {chatHistory.map((msg, index) => (
                    <div
                        key={index}
                        style={{
                            alignSelf: msg.sender === "user" ? "flex-end" : "flex-start",
                            background:
                                msg.sender === "user"
                                    ? "linear-gradient(135deg,#5A8DEE,#42E695)"
                                    : "#f3f4f6",
                            color: msg.sender === "user" ? "#fff" : "#111827",
                            padding: "8px 14px",
                            borderRadius: "14px",
                            maxWidth: "75%",
                            wordBreak: "break-word",
                            fontSize: "14px",
                            boxShadow:
                                msg.sender === "user"
                                    ? "0 0 8px rgba(66,230,149,0.3)"
                                    : "0 0 4px rgba(0,0,0,0.08)",
                        }}
                    >
                        <div
                            style={{
                                fontSize: "0.65rem",
                                marginBottom: "4px",
                                opacity: 0.6,
                            }}
                        >
                            {msg.sender === "user" ? "🧑 You" : "🤖 AI"} • {msg.time}
                        </div>
                        <ReactMarkdown
                            children={msg.text}
                            components={{
                                strong: ({ node, ...props }) => (
                                    <strong style={{ color: "#2563eb" }} {...props} />
                                ),
                                li: ({ node, ...props }) => (
                                    <li style={{ marginBottom: "4px" }} {...props} />
                                ),
                            }}
                        />
                    </div>
                ))}
                <div ref={chatEndRef} />
            </div>

            {/* Input */}
            <div
                style={{
                    display: "flex",
                    gap: "8px",
                    padding: "12px",
                    borderRadius: "0px 0px 16px 16px",
                    borderTop: "1px solid #e5e7eb",
                    background: "#f9fafb",
                    flexWrap: "wrap",
                }}
            >
                <input
                    type="text"
                    value={userMessage}
                    onChange={(e) => setUserMessage(e.target.value)}
                    placeholder="💬 Ask your finance question..."
                    style={{
                        flex: 1,
                        padding: "10px 14px",
                        borderRadius: "25px",
                        border: "1px solid #d1d5db",
                        outline: "none",
                        background: "#fff",
                        color: "#111827",
                        fontSize: "14px",
                    }}
                    onKeyDown={(e) => {
                        if (e.key === "Enter") handleSendMessage();
                    }}
                />
                <button
                    onClick={handleSendMessage}
                    disabled={loading}
                    style={{
                        padding: "10px 20px",
                        borderRadius: "25px",
                        border: "none",
                        background: "linear-gradient(135deg,#5A8DEE,#42E695)",
                        color: "white",
                        fontWeight: "bold",
                        cursor: loading ? "not-allowed" : "pointer",
                        minWidth: "100px",
                        transition: "0.3s",
                        boxShadow: "0 0 8px rgba(66,230,149,0.4)",
                    }}
                >
                    {loading ? <span className="loading-dots"></span> : "Send"}
                </button>
            </div>
        </div>
    );
};

export default ChatAI;
