import React, { useState, useEffect } from "react";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, LineChart, Line
} from "recharts";

function Dashboard({ entries }) {
  const [monthData, setMonthData] = useState([]);
  const [bankData, setBankData] = useState([]);
  const [totalBalance, setTotalBalance] = useState(0);

  useEffect(() => {
    // 1️⃣ Month-wise summary (ignore Bank Transfer)
    const realEntries = entries.filter(e => e.category !== "Bank Transfer");
    const monthGrouped = {};

    realEntries.forEach(entry => {
      const date = new Date(entry.date);
      const month = date.toLocaleString("default", { month: "short", year: "numeric" });
      if (!monthGrouped[month]) {
        monthGrouped[month] = { name: month, income: 0, expense: 0, investment: 0, borrow: 0 };
      }

      if (entry.type === "borrow") {
        monthGrouped[month].borrow += entry.amount;
      } else {
        monthGrouped[month][entry.type] += entry.amount;
      }
    });

    const sortedMonthData = Object.values(monthGrouped).sort((a, b) => {
      const [monthA, yearA] = a.name.split(" ");
      const [monthB, yearB] = b.name.split(" ");
      return new Date(`${monthA} 1, ${yearA}`) - new Date(`${monthB} 1, ${yearB}`);
    });

    setMonthData(sortedMonthData);

    const bankGrouped = {};
    entries.forEach(entry => {
      const bank = entry.bank || "Unknown";
      if (!bankGrouped[bank]) {
        bankGrouped[bank] = { name: bank, income: 0, expense: 0, investment: 0, borrow: 0,borrowReturn:0 };
      }

      if (entry.type === "borrow") {
        bankGrouped[bank].borrow += entry.amount;
      } else {
        bankGrouped[bank][entry.type] += entry.amount;
      }
    });

    const banks = Object.values(bankGrouped).map(bankEntry => ({
      ...bankEntry,
      balance: ((bankEntry.income || 0) + (bankEntry.borrowReturn || 0)) 
       - ((bankEntry.expense || 0) + (bankEntry.investment || 0) + (bankEntry.borrow || 0))
    }));

    const total = banks.reduce((sum, b) => sum + b.balance, 0);

    setBankData(banks);
    setTotalBalance(total);

  }, [entries]);

  return (
    <div className="container my-2">
      <h2 className="mb-3">Dashboard</h2>
      <p className="text-muted">Overview of finances by month and bank.</p>

      {/* Month-wise Summary */}
      <div className="card mb-4 shadow-sm">
        <div className="card-body">
          <h5 className="card-title">Monthly Summary (Bar Chart)</h5>
          <div style={{ width: "100%", height: 300 }}>
            <ResponsiveContainer>
              <BarChart data={monthData} margin={{ top: 20, right: 30, left: 0, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Bar dataKey="income" fill="#28a745" />
                <Bar dataKey="expense" fill="#dc3545" />
                <Bar dataKey="investment" fill="#007bff" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Monthly Trends */}
      <div className="card mb-4 shadow-sm">
        <div className="card-body">
          <h5 className="card-title">Monthly Trends (Line Chart)</h5>
          <div style={{ width: "100%", height: 300 }}>
            <ResponsiveContainer>
              <LineChart data={monthData} margin={{ top: 20, right: 30, left: 0, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Line type="monotone" dataKey="income" stroke="#28a745" />
                <Line type="monotone" dataKey="expense" stroke="#dc3545" />
                <Line type="monotone" dataKey="investment" stroke="#007bff" />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Overall Balance */}
      <div className="alert alert-info text-center">
        <h5>Total Balance across all banks</h5>
        <strong>₹{(totalBalance || 0).toFixed(2)}</strong>
      </div>

      {/* Bank-wise Summary */}
      <div className="card mb-4 shadow-sm">
        <div className="card-body">
          <h5 className="card-title">Bank-wise Summary</h5>
          <div className="table-responsive">
            <table className="table table-bordered table-hover">
              <thead className="table-light">
                <tr>
                  <th>Bank</th>
                  <th>Income</th>
                  <th>Expense</th>
                  <th>Investment</th>
                  <th>Borrow</th>
                  <th>Borrow Return</th>
                  <th>Balance</th>
                </tr>
              </thead>
              <tbody>
                {bankData.length === 0 ? (
                  <tr>
                    <td colSpan="6" className="text-center">No data available</td>
                  </tr>
                ) : (
                  bankData.map(bank => (
                    <tr key={bank.name}>
                      <td>{bank.name}</td>
                      <td>₹{(bank.income || 0).toFixed(2)}</td>
                      <td>₹{(bank.expense || 0).toFixed(2)}</td>
                      <td>₹{(bank.investment || 0).toFixed(2)}</td>
                      <td>₹{(bank.borrow || 0).toFixed(2)}</td>
                      <td>₹{(bank.borrowReturn || 0).toFixed(2)}</td>
                      <td>₹{(bank.balance || 0).toFixed(2)}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Bank-wise Trends */}
      <div className="row">
        <div className="col-lg-6 mb-4">
          <div className="card shadow-sm">
            <div className="card-body">
              <h5 className="card-title">Bank-wise Trends (Bar Chart)</h5>
              <div style={{ width: "100%", height: 300 }}>
                <ResponsiveContainer>
                  <BarChart data={bankData} margin={{ top: 20, right: 30, left: 0, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Bar dataKey="income" fill="#28a745" />
                    <Bar dataKey="expense" fill="#dc3545" />
                    <Bar dataKey="investment" fill="#007bff" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>
        </div>
        <div className="col-lg-6 mb-4">
          <div className="card shadow-sm">
            <div className="card-body">
              <h5 className="card-title">Bank Balance Trends (Line Chart)</h5>
              <div style={{ width: "100%", height: 300 }}>
                <ResponsiveContainer>
                  <LineChart data={bankData} margin={{ top: 20, right: 30, left: 0, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Line type="monotone" dataKey="balance" stroke="#17a2b8" />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
