import React, { useState } from "react";
import Swal from "sweetalert2";

const banks = ["BOB", "ICICI"];

function BankTransferForm({ addTransfer }) {
  const [fromBank, setFromBank] = useState(banks[0]);
  const [toBank, setToBank] = useState(banks[1]);
  const [amount, setAmount] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!amount || fromBank === toBank) {
      return Swal.fire({
        icon: "error",
        title: "Oops...",
        text: "Please fill all fields and select different banks",
      });
    }

    addTransfer({
      id: Date.now(),
      type: "transfer",
      fromBank,
      toBank,
      amount: parseFloat(amount),
      date: new Date().toISOString().split("T")[0],
    });

    Swal.fire({
      icon: "success",
      title: "Success!",
      text: "Transfer completed successfully!",
      timer: 2500,
      showConfirmButton: false,
    });

    setAmount("");
    setFromBank(banks[0]);
    setToBank(banks[1]);
  };
  return (
    <div className="card shadow-sm mb-4">
      <div className="card-header bg-primary text-white">
        <h5 className="mb-0">Bank Transfer</h5>
      </div>
      <div className="card-body">
        <form onSubmit={handleSubmit}>
          <div className="row g-3">
            <div className="col-md-3 col-6">
              <label className="form-label">From Bank</label>
              <select
                value={fromBank}
                onChange={(e) => setFromBank(e.target.value)}
                className="form-select"
              >
                {banks.map((b, idx) => (
                  <option key={idx} value={b}>{b}</option>
                ))}
              </select>
            </div>

            <div className="col-md-3 col-6">
              <label className="form-label">To Bank</label>
              <select
                value={toBank}
                onChange={(e) => setToBank(e.target.value)}
                className="form-select"
              >
                {banks.map((b, idx) => (
                  <option key={idx} value={b}>{b}</option>
                ))}
              </select>
            </div>

            <div className="col-md-3 col-6">
              <label className="form-label">Amount</label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="₹ Amount"
                className="form-control"
              />
            </div>

            <div className="col-md-3 col-6 d-flex align-items-end">
              <button type="submit" className="btn btn-primary w-100">
                Transfer
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}

export default BankTransferForm;
