import React, { useState } from "react";
import { BsTrash } from "react-icons/bs";
import Swal from "sweetalert2";

function EntriesList({ entries, deleteEntry }) {
  const [sortConfig, setSortConfig] = useState({ key: "date", direction: "desc" });
  const [filterType, setFilterType] = useState("");
  const [filterBank, setFilterBank] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  // Filter & sort
  const sortedEntries = [...entries]
    .filter(e => (filterType ? e.type === filterType : true))
    .filter(e => (filterBank ? e.bank === filterBank : true))
    .sort((a, b) => {
      let valA = a[sortConfig.key];
      let valB = b[sortConfig.key];

      if (sortConfig.key === "amount") {
        valA = parseFloat(valA);
        valB = parseFloat(valB);
      } else if (sortConfig.key === "date") {
        valA = new Date(valA);
        valB = new Date(valB);
      } else {
        valA = valA.toString().toLowerCase();
        valB = valB.toString().toLowerCase();
      }

      if (valA < valB) return sortConfig.direction === "asc" ? -1 : 1;
      if (valA > valB) return sortConfig.direction === "asc" ? 1 : -1;
      return 0;
    });

  const totalPages = Math.ceil(sortedEntries.length / itemsPerPage);
  const paginatedEntries = sortedEntries.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const requestSort = key => {
    let direction = "asc";
    if (sortConfig.key === key && sortConfig.direction === "asc") direction = "desc";
    setSortConfig({ key, direction });
  };

  const uniqueTypes = [...new Set(entries.map(e => e.type))];
  const uniqueBanks = [...new Set(entries.map(e => e.bank))];

  const totalAmount = sortedEntries.reduce((sum, e) => sum + e.amount, 0);

  return (
    <div className="card mb-4">
      <div className="card-body">
        <h5>All Entries</h5>

        <div className="row g-2 mb-3">
          <div className="col-md-3">
            <select
              className="form-select"
              value={filterType}
              onChange={e => setFilterType(e.target.value)}
            >
              <option value="">All Types</option>
              {uniqueTypes.map((t, idx) => (
                <option key={idx} value={t}>{t}</option>
              ))}
            </select>
          </div>
          <div className="col-md-3">
            <select
              className="form-select"
              value={filterBank}
              onChange={e => setFilterBank(e.target.value)}
            >
              <option value="">All Banks</option>
              {uniqueBanks.map((b, idx) => (
                <option key={idx} value={b}>{b}</option>
              ))}
            </select>
          </div>
        </div>

        {paginatedEntries.length === 0 ? (
          <p>No entries available.</p>
        ) : (
          <div className="table-responsive">
            <table className="table table-striped table-hover" style={{ whiteSpace: 'nowrap' }}>
              <thead className="table-dark">
                <tr>
                  <th onClick={() => requestSort("date")} style={{ cursor: "pointer" }}>
                    Date {sortConfig.key === "date" ? (sortConfig.direction === "asc" ? "↑" : "↓") : ""}
                  </th>
                  <th onClick={() => requestSort("type")} style={{ cursor: "pointer" }}>
                    Type {sortConfig.key === "type" ? (sortConfig.direction === "asc" ? "↑" : "↓") : ""}
                  </th>
                  <th>Description</th>
                  <th>Category</th>
                  <th onClick={() => requestSort("bank")} style={{ cursor: "pointer" }}>
                    Bank {sortConfig.key === "bank" ? (sortConfig.direction === "asc" ? "↑" : "↓") : ""}
                  </th>
                  <th onClick={() => requestSort("amount")} style={{ cursor: "pointer" }}>
                    Amount {sortConfig.key === "amount" ? (sortConfig.direction === "asc" ? "↑" : "↓") : ""}
                  </th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {paginatedEntries.map((entry) => {
                  const rowStyle =
                    entry.type === "income"
                      ? { backgroundColor: "#def7e4ff" }
                      : entry.type === "expense"
                        ? { backgroundColor: "#f8e4e6ff" }
                        : {};

                  return (
                    <tr key={entry.id} style={rowStyle}>
                      <td>{entry.date}</td>
                      <td>{entry.type}</td>
                      <td>{entry.description}</td>
                      <td>{entry.category}</td>
                      <td>{entry.bank || "-"}</td>
                      <td>₹{entry.amount.toFixed(2)}</td>
                      <td>
                        <button
                          className="btn btn-sm btn-danger"
                          onClick={() => {
                            Swal.fire({
                              title: 'Are you sure?',
                              text: "Do you really want to delete this entry?",
                              icon: 'warning',
                              showCancelButton: true,
                              confirmButtonColor: '#d33',
                              cancelButtonColor: '#3085d6',
                              confirmButtonText: 'Yes, delete it!'
                            }).then((result) => {
                              if (result.isConfirmed) {
                                deleteEntry(entry.id);
                                Swal.fire(
                                  'Deleted!',
                                  'The entry has been deleted.',
                                  'success'
                                );
                              }
                            });
                          }}
                        >
                          <BsTrash size={16} />
                        </button>
                      </td>
                    </tr>
                  );
                })}
                <tr className="table-secondary fw-bold">
                  <td colSpan="5" className="text-end">Total</td>
                  <td>₹{totalAmount.toFixed(2)}</td>
                  <td></td>
                </tr>
              </tbody>
            </table>
          </div>
        )}

        <div className="d-flex justify-content-between align-items-center mt-3">
          <span>Page {currentPage} of {totalPages}</span>
          <div>
            <button
              className="btn btn-sm btn-outline-primary me-1"
              disabled={currentPage === 1}
              onClick={() => setCurrentPage(currentPage - 1)}
            >Prev</button>
            <button
              className="btn btn-sm btn-outline-primary"
              disabled={currentPage === totalPages}
              onClick={() => setCurrentPage(currentPage + 1)}
            >Next</button>
          </div>
        </div>

      </div>
    </div>
  );
}

export default EntriesList;
