import React, { useState } from "react";
import Swal from "sweetalert2";

// List of banks
const banks = ["BOB", "ICICI"];

const categories = {
  income: ["Salary", "Bonus", "Freelance", "Other"],
  expense: ["Food", "Rent", "Travel", "Utilities", "Other"],
  investment: ["Stocks", "Mutual Fund", "Other"],
  borrow: ["Borrow"],
  borrowReturn: ["Return"]
};

function EntryForm({ addEntry }) {
  const [type, setType] = useState("income");
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("");
  const [bank, setBank] = useState(banks[0]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!description || !amount || !category || !bank) {
      return Swal.fire({
        icon: "error",
        title: "Oops...",
        text: "Please fill all fields",
      });
    }

    addEntry({
      id: Date.now(),
      type,
      description,
      amount: parseFloat(amount),
      category,
      bank,
      date: new Date().toISOString().split("T")[0],
    });

    Swal.fire({
      icon: "success",
      title: "Success!",
      text: "Entry added successfully!",
      timer: 2500,
      showConfirmButton: false,
    });

    setDescription("");
    setAmount("");
    setCategory("");
    setBank(banks[0]);
  };

  return (
    <div className="card shadow-sm mb-4">
      <div className="card-header bg-success text-white">
        <h5 className="mb-0">Add New Entry</h5>
      </div>
      <div className="card-body">
        <form onSubmit={handleSubmit}>
          <div className="row g-3 align-items-end">
            <div className="col-md-2 col-6">
              <label className="form-label">Type</label>
              <select
                value={type}
                onChange={(e) => setType(e.target.value)}
                className="form-select"
              >
                <option value="income">Income</option>
                <option value="expense">Expense</option>
                <option value="investment">Investment</option>
                <option value="borrow">Borrow</option>
                <option value="borrowReturn">Borrow Return</option>
              </select>
            </div>

            <div className="col-md-3 col-6">
              <label className="form-label">Description</label>
              <input
                type="text"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Description"
                className="form-control"
              />
            </div>

            <div className="col-md-2 col-6">
              <label className="form-label">Amount</label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="₹ Amount"
                className="form-control"
              />
            </div>

            <div className="col-md-2 col-6">
              <label className="form-label">Category</label>
              <select
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className="form-select"
              >
                <option value="">Select Category</option>
                {categories[type].map((cat, idx) => (
                  <option key={idx} value={cat}>
                    {cat}
                  </option>
                ))}
              </select>
            </div>

            <div className="col-md-2 col-6">
              <label className="form-label">Bank</label>
              <select
                value={bank}
                onChange={(e) => setBank(e.target.value)}
                className="form-select"
              >
                <option value="">Select Bank</option>
                {banks.map((b, idx) => (
                  <option key={idx} value={b}>
                    {b}
                  </option>
                ))}
              </select>
            </div>

            <div className="col-md-1 col-6 d-flex align-items-end">
              <button type="submit" className="btn btn-success w-100">
                + Add
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}

export default EntryForm;
