import React from "react";
import { BsCashStack, BsArrowDownCircle, BsGraphUp, BsBank } from "react-icons/bs";
import { FaHandHoldingUsd } from "react-icons/fa";

function Summary({ entries }) {
  const filteredEntries = entries.filter(e => e.category !== "Bank Transfer");

  const totalIncome = filteredEntries
    .filter(e => e.type === "income")
    .reduce((sum, e) => sum + e.amount, 0);

  const totalExpense = filteredEntries
    .filter(e => e.type === "expense")
    .reduce((sum, e) => sum + e.amount, 0);

  const totalInvestment = filteredEntries
    .filter(e => e.type === "investment")
    .reduce((sum, e) => sum + e.amount, 0);

  const totalBalance = totalIncome - totalExpense - totalInvestment;

  const cardStyle = {
    borderRadius: "15px",
    color: "white",
    padding: "10px 20px",
    transition: "transform 0.2s",
  };

  const hoverEffect = {
    transform: "scale(1.05)",
  };

  return (
    <div className="row mb-4 g-3 text-center">
      <div className="col-md-3 col-12">
        <div className="card shadow-sm"
          style={{
            ...cardStyle,
            background: "linear-gradient(135deg, #17a2b8, #66e0f0)"
          }}
          onMouseEnter={e => e.currentTarget.style.transform = "scale(1.05)"}
          onMouseLeave={e => e.currentTarget.style.transform = "scale(1)"}>
          <div className="card-body">
            <BsBank size={40} className="mb-2" />
            <h6>Balance</h6>
            <h2 className="fw-bold">₹{totalBalance.toFixed(2)}</h2>
          </div>
        </div>
      </div>

      <div className="col-md-3 col-12">
        <div className="card shadow-sm"
          style={{
            ...cardStyle,
            background: "linear-gradient(135deg, #28a745, #71dd8a)"
          }}
          onMouseEnter={e => e.currentTarget.style.transform = "scale(1.05)"}
          onMouseLeave={e => e.currentTarget.style.transform = "scale(1)"}>
          <div className="card-body">
            <BsCashStack size={40} className="mb-2" />
            <h6>Total Income</h6>
            <h2 className="fw-bold">₹{totalIncome.toFixed(2)}</h2>
          </div>
        </div>
      </div>

      <div className="col-md-3 col-12">
        <div className="card shadow-sm"
          style={{
            ...cardStyle,
            background: "linear-gradient(135deg, #dc3545, #ff7f7f)"
          }}
          onMouseEnter={e => e.currentTarget.style.transform = "scale(1.05)"}
          onMouseLeave={e => e.currentTarget.style.transform = "scale(1)"}>
          <div className="card-body">
            <BsArrowDownCircle size={40} className="mb-2" />
            <h6>Total Expense</h6>
            <h2 className="fw-bold">₹{totalExpense.toFixed(2)}</h2>
          </div>
        </div>
      </div>

      <div className="col-md-3 col-12">
        <div className="card shadow-sm"
          style={{
            ...cardStyle,
            background: "linear-gradient(135deg, #007bff, #66b3ff)"
          }}
          onMouseEnter={e => e.currentTarget.style.transform = "scale(1.05)"}
          onMouseLeave={e => e.currentTarget.style.transform = "scale(1)"}>
          <div className="card-body">
            <BsGraphUp size={40} className="mb-2" />
            <h6>Total Investment</h6>
            <h2 className="fw-bold">₹{totalInvestment.toFixed(2)}</h2>
          </div>
        </div>
      </div>
      <div className="col-md-3 col-12 mb-3">
        <div className="card shadow-sm"
          style={{
            ...cardStyle,
            background: "linear-gradient(135deg, #ffc107, #ffdd57)"
          }}
          onMouseEnter={e => e.currentTarget.style.transform = "scale(1.05)"}
          onMouseLeave={e => e.currentTarget.style.transform = "scale(1)"}>
          <div className="card-body text-white text-center">
            <FaHandHoldingUsd size={40} className="mb-2" />
            <h6>Total Borrowed</h6>
            <h2 className="fw-bold">
              ₹{(
                entries
                  .filter(e => e.type === "borrow")
                  .reduce((sum, e) => sum + (e.amount || 0), 0)
                -
                entries
                  .filter(e => e.type === "borrowReturn")
                  .reduce((sum, e) => sum + (e.amount || 0), 0)
              ).toFixed(2)}

            </h2>
          </div>
        </div>
      </div>

    </div>
  );
}

export default Summary;
